  [415423] = { "ハンターがマムシの相を帯び、遠隔および近接の自動攻撃でマナを回復するようになりますが、与えるダメージの合計が$N1%減少します。さらに、$N3秒ごとに最大マナの$N2%を得ます。得られるマナは武器の速度に基づきます。一度に有効にできるAspectは一つだけです。", "遠隔と近接の自動攻撃で基本マナの一定割合を回復しますが、与えるダメージの合計が$N1%減少します。さらに、$N3秒ごとに最大マナの$N2%を獲得します。", 0x5c074219, 0xcddcfcf7, "uu" },
  [415449] = { "Runeが刻まれたWaistスロットのアイテムを装備すると、このスロットのアビリティが有効になります。", nil, 0xa309a047, nil, "um" },
  [415450] = { "Runeが刻まれたFeetスロットのアイテムを装備すると、このスロットのアビリティが有効になります。", nil, 0x94e65c6e, nil, "um" },
  [415918] = { "外套にCrimson Tempestのルーンを刻みます：\r\n\n$I1\r\n$N1ヤード以内のすべての敵を切り裂き、時間とともにBleedさせるフィニッシュ技です。コンボポイントが多いほど長く持続し、ダメージも増加します。\r\n\n1ポイント：4秒かけて$N3のダメージ。\r\n 2ポイント：6秒かけて$N6のダメージ。\r\n 3ポイント：8秒かけて$N9のダメージ。\r\n 4ポイント：10秒かけて$N12のダメージ。\r\n 5ポイント：12秒かけて$N15のダメージ。\r\n\nCrimson Tempestは、Ruptureによって発動する、またはRuptureを強化するすべてのタレントと効果の恩恵を受けます。", nil, 0xe3ea95b8, nil, "um" },
  [415922] = { "外套にBlunderbussのルーンを刻みます：\r\n\n$I1\r\n前方の円錐範囲にいる敵最大$N1体にマスケット銃の一斉射撃を放ち、$N2のPhysicalダメージを与えます。", nil, 0xce5a37fe, nil, "um" },
  [415926] = { "ブーツにWaylayのルーンを刻みます：\r\n\n$I1\r\nAmbushとBackstabの命中で対象の体勢を崩し、$D1の間、近接攻撃の間隔を$N1%延ばし、移動速度を$N2%低下させます。", nil, 0x8f27a210, nil, "um" },
  [415934] = { "ブーツにSpell Powerのルーンを刻みます：\r\n\n$I1\r\nすべての呪文のクリティカルダメージボーナスが$N1%増加します。", nil, 0xf49948f2, nil, "um" },
  [415936] = { "手袋にLiving Bombのルーンを刻みます：\r\n\n$I1\r\n対象はLiving Bombとなり、$D1かけて$N1のFireダメージを受けます。$D2後、または呪文が解除されると、対象は爆発し、$N5ヤード以内のすべての敵に$N4のFireダメージを与えます。\r\n\nLiving Bombは、Scorchによって発動する、またはScorchを強化するすべてのタレントと効果の恩恵を受けます。", nil, 0x7a583662, nil, "um" },
  [415939] = { "脚部にMass Regenerationのルーンを刻みます：\r\n\n$I1\r\n対象のプレイヤーから$N1ヤード以内にいる、そのプレイヤーのパーティーメンバー全員の体力を$D1かけて$N2回復し、それぞれに$D2の間Temporal Beaconを付与します。\r\n\nTemporal Beacon\r\n$I2\r\n対象の時空間の位置を記録します。術者が与えたArcaneダメージの$N5%が、術者の現在のTemporal Beaconの対象それぞれへのクロノマンシーの治療に変換されます。この治療は自分に対しては$N6%減少し、複数の対象にダメージを与えるArcane呪文によるダメージの場合はさらに$N7%減少します。", nil, 0x7d1b407b, nil, "um" },
  [415942] = { "胸部か法衣にEnlightenmentのルーンを刻みます：\r\n\n$I1\r\nマナが$N2%を超えている間、与えるダメージが$N1%増加します。マナが$N3%を下回っている間、詠唱中もマナ回復の$N4%が継続します。", nil, 0xe36c7b47, nil, "um" },
  [415948] = { "ベルトにSpellfrost Boltのルーンを刻みます：\r\n\n$I1\r\n敵にスペルフロストの矢を放ち、$N1のSpellfrostダメージを与え、$D1の間、移動速度を$N2%低下させます。この呪文は対象のFrostとArcaneの耐性のうち低い方で判定され、FrostとArcane両方のダメージとして扱われます。", nil, 0x0e2ee4df, nil, "um" },
  [415991] = { "兜にPain and Sufferingのルーンを刻みます：\r\n\n$I1\r\nMind Blast、Mind Spike、Mind Flayが、対象にかかっているShadow Word: Pain、Void Plague、Vampiric Touchのいずれか一つの効果時間を最大まで更新します。更新されるのは、常に残り時間が最も短いものです。", nil, 0x1765a845, nil, "um" },
  [415995] = { "胸部か法衣にSerendipityのルーンを刻みます：\r\n\n$I1\r\nFlash Healで回復すると、$D1の間、次のLesser Heal、Heal、Greater Heal、Prayer of Healingの詠唱時間が$N1%短縮されます。最大$N3回まで累積します。", nil, 0x15382fc4, nil, "um" },
  [415996] = { "手袋にMind Searのルーンを刻みます：\r\n\n$I1\r\n影の魔法を爆発させて敵の対象と近くの敵を傷つけ、$D2の間、$D1ごとに、対象から$N4ヤード以内のすべての敵に$N1のShadowダメージを与えます。", nil, 0xc0148127, nil, "um" },
  [415997] = { "胸部か法衣にStrength of Soulのルーンを刻みます：\r\n\n$I1\r\nLesser Heal、Heal、Greater Heal、Flash Healが、回復した対象のWeakened Soulの残り時間を$D1短縮します。さらに、Power Word: Shieldの対象は、ダメージが吸収されてもダメージを受けたことで怒りを得るようになり、Righteous FuryはPower Word: Shieldで吸収されたダメージを治療であるかのように扱って発動します。", nil, 0x28fd638c, nil, "um" },
